    """Check if the file exists."""
    if not os.path.exists(filepath):
        return False, f"File does not exist: {filepath}"
    return True, "File exists"

def validate_file_not_empty(filepath, check_name):
    """Check if the file is not empty."""
    if not os.path.exists(filepath):
        return False, "File does not exist"
    if os.path.getsize(filepath) == 0:
        return False, "File is empty"
    return True, "File is not empty"

def validate_has_expected_columns(filepath, check_name, expected_columns):
    """Check if the file has the expected columns."""
    if not os.path.exists(filepath):
        return False, f"File does not exist: {filepath}"
    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            reader = csv.DictReader(f)
            actual_columns = reader.fieldnames
            if actual_columns is None:
                return False, "File has no header row"
            actual_columns_set = set(actual_columns)
            expected_columns_set = set(expected_columns)
            missing = expected_columns_set - actual_columns_set
            if missing:
                return False, f"Missing columns: {missing}"
            return True, f"All expected columns present: {expected_columns}"
    except Exception as e:
        return False, f"Error reading file: {e}"

def validate_has_data_rows(filepath, check_name):
    """Check if the file has at least one data row."""
    if not os.path.exists(filepath):
        return False, "File does not exist"
    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            reader = csv.DictReader(f)
            row_count = sum(1 for _ in reader)
            if row_count == 0:
                return False, "File has no data rows"
            return True, f"File has {row_count} data rows"
    except Exception as e:
        return False, f"Error reading file: {e}"

